(function(g){'use strict';const L=g.DecideLegacyLoot||(typeof require==='function'?require('./legacy-loot.js'):null),A=g.DecideCatalogEconomy||(typeof require==='function'?require('./catalog-economy.js'):null);
function validate(list){if(!Array.isArray(list)||list.length>26||list.some(x=>!x||!L.LOOT_LOOKUP_TYPES.includes(x.kind)||typeof x.id!=='string'||x.id.length>200||typeof x.name!=='string'||!x.name.trim()||x.name.length>160))throw Error('ข้อมูลของดรอปไม่ถูกต้อง');return list;}
function prepare(e,rows){if(e.catalogDrops!==undefined){validate(e.catalogDrops);return;}const db={};for(const row of rows)(db[row.kind]??=[]).push(row);let seed=2166136261;for(const ch of e.id)seed=Math.imul(seed^ch.charCodeAt(0),16777619)>>>0;const roll=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const drops=[];if(!e.training)for(const u of e.units.filter(u=>u.side==='enemy')){const monster=db.monster?.find(m=>m.id===u.monsterId&&m.enabled!==false);if(!monster)continue;for(const name of L.rollMonsterLootDrop(monster,db,roll(),roll())){for(const kind of L.LOOT_LOOKUP_TYPES){const item=db[kind]?.find(r=>r.name===name&&r.enabled!==false);if(item){drops.push({kind,id:item.id,name:item.name});break;}}}}e.catalogDrops=validate(drops);}
function grant(next,e){const drops=e.status==='won'?validate(e.catalogDrops||[]):[];if(!drops.length)return [];const adapter=g.DecideCatalogEconomy||A;const inv=adapter.validate(next.catalogInventory);for(const d of drops){if(['item','dropItem'].includes(d.kind))inv.items.push(d.name);else inv.gearStash.push({refType:d.kind,name:d.name});}next.catalogInventory=adapter.validate(inv);return drops.map(x=>({...x}));}
const api={validate,prepare,grant};g.DecideCatalogLoot=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
